package com.smartmart.order.repository; import com.smartmart.order.entity.CustomerOrder; import org.springframework.data.jpa.repository.*; import java.util.*; public interface CustomerOrderRepository extends JpaRepository<CustomerOrder,Long>{@EntityGraph(attributePaths="items.product") List<CustomerOrder> findByUserIdOrderByCreatedAtDesc(Long id); @EntityGraph(attributePaths="items.product") Optional<CustomerOrder> findWithItemsById(Long id); @EntityGraph(attributePaths="items.product") @Query("select o from CustomerOrder o order by o.createdAt desc") List<CustomerOrder> findAllWithItems();}
